extern uint8_t *lz_tab;
static uint8_t tab_space[1024];
static uint8_t tab_lut[16], tab_ok;

static void lz_setlut(const uint8_t *lut) {
    if (tab_ok && !memcmp(lut, tab_lut, 16)) return;
    if (!lz_tab) {
        unsigned a = ((unsigned)tab_space + 255) & ~255u;
        if (((a >> 8) & 255) == 255) a += 256;
        lz_tab = (uint8_t *)a;
    }
    memcpy(tab_lut, lut, 16);
    tab_ok = 1;
    for (int i = 0; i < 16; i++) {
        memset(lz_tab + i * 16, lut[i], 16);
        memcpy(lz_tab + 256 + i * 16, lut, 16);
    }
}
