static const uint8_t *bg_top(int view) {
    return g_seat ? (view ? APTR(BG_ENEMY2_TOP) : APTR(BG_HOME2_TOP)) : (view ? APTR(BG_ENEMY_TOP) : APTR(BG_HOME_TOP));
}
static const uint8_t *bg_bot(int view) {
    return g_seat ? (view ? APTR(BG_ENEMY2_BOT) : APTR(BG_HOME2_BOT)) : (view ? APTR(BG_ENEMY_BOT) : APTR(BG_HOME_BOT));
}
static const uint8_t *bg_col(int view, int x) {
    if (x < BG_SPLIT) return bg_top(view) + x * FBS;
    return bg_bot(view) + (x - BG_SPLIT) * FBS;
}

static const uint8_t seam_tab[PAN_N + 1] = PAN_SEAM;

static const int16_t *knots(int step, int view) { return (const int16_t *)(APTR(PANK)) + (step * 2 + view) * PAN_KNOTS; }
#define KNOT_Y(k) ((k) * 15 < 239 ? (k) * 15 : 239)

void pan_run(uint8_t *dst, const uint8_t *src, unsigned len, unsigned n, unsigned step, unsigned frac);
static void copy_run(int dy, int sy, int len, int view, int s8, int xa, int xb, int ox) {
    if (len <= 0 || xb <= xa) return;
    long a0 = 40960L + (((long)(2 * (xa - ox) - 319) * s8) >> 1);
    int x = xa;
    while (x < xb) {
        long acc = a0 + (long)(x - xa) * s8;
        int c = (int)(acc >> 8);
        int n, step = s8, frac = (int)(acc & 255);
        if (c < 0 || c > 319) {
            n = c < 0 ? (int)((-acc + s8 - 1) / s8) : xb - x;
            c = c < 0 ? 0 : 319; step = 0; frac = 0;
        } else {
            long lim = (c < BG_SPLIT ? BG_SPLIT : 320) * 256L;
            n = (int)((lim - acc + s8 - 1) / s8);
        }
        if (n < 1) n = 1;
        if (n > xb - x) n = xb - x;
        if (n > 255) n = 255;
        pan_run(hw_back + x * FBS + dy, bg_col(view, c) + sy, (unsigned)len, (unsigned)n, (unsigned)step, (unsigned)frac);
        x += n;
    }
}

static void bg_view(int view) {
    if (!g_ox && !g_oy && g_clip0 == 0 && g_clip1 == 240 && g_cx0 == 0 && g_cx1 == 320) {
        memcpy(hw_back, bg_top(view), BG_SPLIT * FBS);
        memcpy(hw_back + BG_SPLIT * FBS, bg_bot(view), (320 - BG_SPLIT) * FBS);
        return;
    }
    int c0 = g_clip0, c1 = g_clip1, ox = g_ox, oy = g_oy;
    int dy = oy, sy = 0, len = 240;
    if (dy < c0) { sy += c0 - dy; len -= c0 - dy; dy = c0; }
    if (dy + len > c1) len = c1 - dy;
    int xa = ox > 0 ? ox : 0, xb = ox < 0 ? 320 + ox : 320;
    if (xa < g_cx0) xa = g_cx0;
    if (xb > g_cx1) xb = g_cx1;
    copy_run(dy, sy, len, view, 256, xa, xb, ox);
}

static const uint8_t *pan_runs(const uint8_t *tab, int step) { return tab + (tab[step * 2] | tab[step * 2 + 1] << 8); }
#define PRUN 5

static void bg_runs(const uint8_t *runs, int n, int xa, int xb) {
    int c0 = g_clip0, c1 = g_clip1, ox = g_ox, oy = g_oy;
    uint8_t cr[4 * 40];
    int m = 0;
    for (int i = 0; i < n && m < 40; i++, runs += PRUN) {
        int dy = runs[0] + oy, sy = runs[1], len = runs[2];
        if (dy < c0) { int k = c0 - dy; dy += k; sy += k; len -= k; }
        if (dy + len > c1) len = c1 - dy;
        if (len <= 0) continue;
        if (runs[4]) {
            copy_run(dy, sy, len, runs[3], 256 + (int8_t)runs[4], xa, xb, ox);
            continue;
        }
        cr[m * 4] = (uint8_t)dy; cr[m * 4 + 1] = (uint8_t)sy; cr[m * 4 + 2] = (uint8_t)len; cr[m * 4 + 3] = runs[3];
        m++;
    }
    if (!m) return;

    static uint8_t code[40 * 12 + 8];
    uint8_t *q = code;
    for (int v = 0; v < 2; v++) {
        if (v) { q[0] = 0xDD; q[1] = 0x2A; q[2] = (uint8_t)(long)&pg_enemy; q[3] = (uint8_t)((long)&pg_enemy >> 8); q[4] = (uint8_t)((long)&pg_enemy >> 16); q += 5; }
        for (int i = 0; i < m; i++) {
            const uint8_t *c = cr + i * 4;
            if (c[3] != v) continue;
            q[0] = 0xED; q[1] = 0x22; q[2] = (uint8_t)(c[1] - 128);
            q[3] = 0xED; q[4] = 0x13; q[5] = (uint8_t)(c[0] - 128);
            q[6] = 0x01; q[7] = c[2]; q[8] = 0; q[9] = 0;
            q[10] = 0xED; q[11] = 0xB0;
            q += 12;
        }
    }
    *q = 0xC9;

    int xs = BG_SPLIT + ox;
    if (xs < xa) xs = xa;
    if (xs > xb) xs = xb;
    if (xs > xa)
        pan_gcols(hw_back + xa * FBS, bg_col(VIEW_HOME, xa - ox), bg_col(VIEW_ENEMY, xa - ox), (unsigned)(xs - xa), code);
    if (xb > xs)
        pan_gcols(hw_back + xs * FBS, bg_col(VIEW_HOME, xs - ox), bg_col(VIEW_ENEMY, xs - ox), (unsigned)(xb - xs), code);
}

#define WIPE_FROM 36
#define WIPE_R 48
void pan_dither(uint8_t *dst, const uint8_t *src, unsigned ncols, unsigned phase, void *const *code, unsigned step, unsigned frac);
static uint8_t dcode[4][WIPE_R * 6 + 1];
static void *const dptr[4] = { dcode[0], dcode[1], dcode[2], dcode[3] };
static const uint8_t bayer[4][4] = { { 0, 8, 2, 10 }, { 12, 4, 14, 6 }, { 3, 11, 1, 9 }, { 15, 7, 13, 5 } };

static int seam_b(int step) { const uint8_t *rb = pan_runs(APTR(PANB), step); return rb[0] >= 239 ? 240 : rb[0]; }

static int wipe_front(int step) {
    if (step <= WIPE_FROM) return -WIPE_R;
    int x = step >= PAN_N - 1 ? 256 : (step - WIPE_FROM) * 256 / (PAN_N - 1 - WIPE_FROM);
    int u = x * x / 256 * (768 - 2 * x) / 256;
    int sa = seam_tab[step], sb = seam_b(step);
    return sa - WIPE_R + (sb - sa + WIPE_R) * u / 256;
}

int pan_blend(int step, int y) {
    if (step <= WIPE_FROM || step >= PAN_N) return step >= PAN_N ? 256 : 0;
    int f = wipe_front(step), sb = seam_b(step);
    if (y >= sb) return 0;
    int l = y < f ? 256 : y >= f + WIPE_R ? 0 : (f + WIPE_R - y) * 256 / WIPE_R;
    if (sb - y < 24) l = l * (sb - y) / 24;
    return l;
}

static void dither_cols(int s8, int xa, int xb, int ox) {
    long a0 = 40960L + (((long)(2 * (xa - ox) - 319) * s8) >> 1);
    int x = xa;
    while (x < xb) {
        long acc = a0 + (long)(x - xa) * s8;
        int c = (int)(acc >> 8), n, st = s8, frac = (int)(acc & 255);
        if (c < 0 || c > 319) {
            n = c < 0 ? (int)((-acc + s8 - 1) / s8) : xb - x;
            c = c < 0 ? 0 : 319; st = 0; frac = 0;
        } else {
            long lim = (c < BG_SPLIT ? BG_SPLIT : 320) * 256L;
            n = (int)((lim - acc + s8 - 1) / s8);
        }
        if (n < 1) n = 1;
        if (n > xb - x) n = xb - x;
        pan_dither(hw_back + x * FBS, bg_col(VIEW_ENEMY, c), (unsigned)n, (unsigned)(x & 3), dptr, (unsigned)st, (unsigned)frac);
        x += n;
    }
}

static __attribute__((noinline)) void pan_band(int step, int f, int xa, int xb) {
    const uint8_t *rb = pan_runs(APTR(PANB), step);
    int ya = f > seam_tab[step] ? f : seam_tab[step], yb = f + WIPE_R, oy = g_oy, ox = g_ox;
    const uint8_t *r = rb + 2;
    for (int i = rb[1]; i > 0; i--, r += PRUN) {
        if (!r[3]) continue;
        int y0 = r[0] > ya ? r[0] : ya, y1 = r[0] + r[2] < yb ? r[0] + r[2] : yb;
        if (y1 <= y0) continue;
        bool any = false;
        for (int p = 0; p < 4; p++) {
            uint8_t *q = dcode[p];
            for (int y = y0; y < y1; y++) {
                int d = y + oy;
                if (d < g_clip0 || d >= g_clip1 || bayer[y & 3][p] >= (pan_blend(step, y) + 8) >> 4) continue;
                q[0] = 0xDD; q[1] = 0x7E; q[2] = (uint8_t)(r[1] + y - r[0] - 128);
                q[3] = 0xFD; q[4] = 0x77; q[5] = (uint8_t)(d - 128);
                q += 6;
                any = true;
            }
            *q = 0xC9;
        }
        if (any) dither_cols(256 + (int8_t)r[4], xa, xb, ox);
    }
}

void draw_bg_pan(int step) {
    int c0 = g_clip0, c1 = g_clip1, ox = g_ox, oy = g_oy;

    if (oy > 0 && c0 < oy) fill_rect(0, c0, 320, oy - c0, C_BLACK);
    if (oy < 0 && 240 + oy < c1) fill_rect(0, 240 + oy, 320, c1 - (240 + oy), C_BLACK);
    if (ox > 0) fill_rect(0, 0, ox, 240, C_BLACK);
    if (ox < 0) fill_rect(320 + ox, 0, -ox, 240, C_BLACK);
    if (step <= 0 || step >= PAN_N) { bg_view(step <= 0 ? VIEW_HOME : VIEW_ENEMY); return; }
    int xa = ox > 0 ? ox : 0, xb = ox < 0 ? 320 + ox : 320;
    if (xa < g_cx0) xa = g_cx0;
    if (xb > g_cx1) xb = g_cx1;
    if (xb <= xa) return;
    const uint8_t *ra = pan_runs(APTR(PAN), step);
    int f = wipe_front(step), fs = f + oy;
    if (fs > c0) {
        const uint8_t *rb = pan_runs(APTR(PANB), step);
        g_clip1 = fs < c1 ? fs : c1;
        bg_runs(rb + 2, rb[1], xa, xb);
        g_clip1 = c1;
    }
    if (fs < c1) {
        g_clip0 = fs > c0 ? fs : c0;
        bg_runs(ra + 2, ra[1], xa, xb);
        g_clip0 = c0;
        if (f + WIPE_R > 0) pan_band(step, f, xa, xb);
    }
}

int pan_seam(int step) {
    if (step <= 0) return 0;
    if (step >= PAN_N) return 240;
    return seam_tab[step];
}

void pan_place(int step, int view, int sx, int sy, int *dx, int *dy) {
    *dx = 0; *dy = 0;
    if (step <= 0) { if (view != VIEW_HOME) *dy = -1000; return; }
    if (step >= PAN_N) { if (view != VIEW_ENEMY) *dy = 1000; return; }
    const int16_t *kn = knots(step, view);
    int t = 2 * sy + 1;
    int k = 0;
    while (k < PAN_KNOTS - 2 && kn[k + 1] < t) k++;
    int ky = KNOT_Y(k), kw = KNOT_Y(k + 1) - ky, rd = kn[k + 1] - kn[k];
    int y = rd > 0 ? ky + (t - kn[k]) * kw / rd : ky;
    *dy = y - sy;
    if (y < 0 || y > 239) return;

    const uint8_t *r = pan_runs(view == VIEW_HOME ? APTR(PAN) : APTR(PANB), step);
    int n = r[1], best = 999, ds = 0;
    for (r += 2; n > 0; n--, r += PRUN) {
        if (r[3] != view) continue;
        int dd = y < r[0] ? r[0] - y : y >= r[0] + r[2] ? y - (r[0] + r[2]) + 1 : 0;
        if (dd < best) { best = dd; ds = (int8_t)r[4]; }
    }
    if (ds) *dx = (int)((((long)(2 * sx - 319) << 8) / (256 + ds) + 319) >> 1) - sx;
}

int pan_row(int step, int view, int src_y) {
    int dx, dy;
    pan_place(step, view, 160, src_y, &dx, &dy);
    return src_y + dy;
}

void sprite_rect(const uint8_t *spr, int *x, int *y, int *w, int *h) {
    *y = spr[0]; *x = spr[1] | spr[2] << 8;
    *h = spr[3]; *w = spr[4] | spr[5] << 8;
}

#define RING 8
static uint8_t ring[(RING + 1) * FBS];
static int rg_r, rg_w;
static uint8_t *rg_slot(void) {
    int k = rg_r % RING;
    if (!k && rg_r) memcpy(ring, ring + RING * FBS, (size_t)rg_w);
    return ring + (k + 1) * FBS;
}

extern const uint8_t *pd_ptr, *pd_hs, *pd_lut;
extern uint8_t pd_bits, pd_pos, pd_last;
void pd_pixels(uint8_t *dst, unsigned n);
static int ps_, pl_;
static void pd_row(uint8_t *d) {
    uint8_t R = *pd_hs++;
    if (R < 0xF0) {
        ps_ += (R >> 4) - 7; pl_ += (R & 15) - 7;
        pd_pixels(d + ps_, (unsigned)pl_);
    } else if (R == 0xF1) {
        uint8_t n = *pd_hs++;
        const uint8_t *s = pd_hs;
        pd_hs += 2 * n;
        for (uint8_t k = 0; k < n; k++) pd_pixels(d + s[2 * k], s[2 * k + 1]);
        if (n) { ps_ = s[0]; pl_ = s[1]; }
    }
}

int g_cx0 = 0, g_cx1 = 320;

void draw_lz(const uint8_t *p, int dy, int cy0, int cy1) {
    int col = p[0] + dy + g_oy, row = (p[1] | p[2] << 8) + g_ox;
    int w = p[3], h = p[4] | p[5] << 8;
    if (cy0 < g_clip0) cy0 = g_clip0;
    if (cy1 > g_clip1) cy1 = g_clip1;
    int xl = g_cx0 > 0 ? g_cx0 : 0, xr = g_cx1 < 320 ? g_cx1 : 320;
    if (col >= cy1 || col + w <= cy0 || row >= xr || row + h <= xl) return;
    bool pd = p[6] == 0xFF;
    lz_setlut(p + 7);
    if (pd) {
        pd_lut = lz_tab + 256;
        pd_hs = p + 24;
        pd_ptr = p + (p[22] | p[23] << 8);
        pd_pos = 8; pd_last = 0;
        ps_ = 0; pl_ = 1;
    } else p += 7 + p[6];
    if (col >= cy0 && col + w <= cy1 && row >= xl && row + h <= xr) {
        uint8_t *d = hw_back + row * FBS + col;
        if (pd) for (int r = 0; r < h; r++, d += FBS) pd_row(d);
        else for (int r = 0; r < h; r++, d += FBS) p = lz_row(d, p);
        return;
    }
    if (col >= cy0 && col + w <= cy1) {
        static uint8_t save[FBS];
        uint8_t *seam = NULL;
        int r = 0;
        if (row < xl) {
            rg_w = w;
            for (rg_r = 0; row + rg_r < xl; rg_r++) {
                uint8_t *sl = rg_slot();
                if (pd) pd_row(sl); else p = lz_row(sl, p);
            }
            if (xl > 0) {
                seam = hw_back + (xl - 1) * FBS + col;
                memcpy(save, seam, (size_t)w);
                memcpy(seam, ring + ((rg_r - 1) % RING + 1) * FBS, (size_t)w);
            } else if (rg_r < h) {
                uint8_t *sl = rg_slot(), *d0 = hw_back + col;
                memcpy(sl, d0, (size_t)w);
                if (pd) pd_row(sl); else p = lz_row(sl, p);
                memcpy(d0, sl, (size_t)w);
                rg_r++;
            }
            r = rg_r;
        }
        uint8_t *d = hw_back + (row + r) * FBS + col;
        if (pd) for (; r < h && row + r < xr; r++, d += FBS) pd_row(d);
        else for (; r < h && row + r < xr; r++, d += FBS) p = lz_row(d, p);
        if (seam) memcpy(seam, save, (size_t)w);
        return;
    }
    int a = cy0 > col ? cy0 - col : 0, b = cy1 - col < w ? cy1 - col : w;
    rg_w = w;
    for (rg_r = 0; rg_r < h; rg_r++) {
        int x = row + rg_r;
        if (x >= xr) break;
        uint8_t *sl = rg_slot();
        bool vis = x >= xl && b > a;
        uint8_t *d = hw_back + x * FBS + col;
        if (vis) memcpy(sl + a, d + a, (size_t)(b - a));
        if (pd) pd_row(sl);
        else p = lz_row(sl, p);
        if (vis) memcpy(d + a, sl + a, (size_t)(b - a));
    }
}

static int runs_dx;
void runs_at(const uint8_t *p, uint8_t c, int dx, int dy) {
    runs_dx = dx;
    draw_runs(p, c, dy, 0, 240);
    runs_dx = 0;
}
void draw_runs(const uint8_t *p, uint8_t c, int dy, int cy0, int cy1) {
    int col = p[0] + dy, row = (p[1] | p[2] << 8) + runs_dx;
    int w = p[3], h = p[4] | p[5] << 8;
    if (cy0 < g_clip0) cy0 = g_clip0;
    if (cy1 > g_clip1) cy1 = g_clip1;
    if (col >= cy1 || col + w <= cy0) return;
    p += 6;
    for (int r = 0; r < h; r++) {
        uint8_t *d = hw_back + (row + r) * FBS;
        bool vis = row + r >= g_cx0 && row + r < g_cx1;
        int y = col;
        for (;;) {
            uint8_t s = *p++;
            if (s == 0xFF) break;
            int n = *p++;
            y += s;
            int a = y < cy0 ? cy0 : y, b = y + n > cy1 ? cy1 : y + n;
            if (vis && b > a) memset(d + a, c, (size_t)(b - a));
            y += n;
        }
    }
}

void fill_rect(int x, int y, int w, int h, uint8_t c) {
    if (x < g_cx0) { w += x - g_cx0; x = g_cx0; }
    if (y < g_clip0) { h += y - g_clip0; y = g_clip0; }
    if (x + w > g_cx1) w = g_cx1 - x;
    if (y + h > g_clip1) h = g_clip1 - y;
    if (w <= 0 || h <= 0) return;
    uint8_t *d = hw_back + x * FBS + y;
    while (w--) { memset(d, c, (size_t)h); d += FBS; }
}

void frame_rect(int x, int y, int w, int h, uint8_t c) {
    fill_rect(x, y, w, 1, c);
    fill_rect(x, y + h - 1, w, 1, c);
    fill_rect(x, y, 1, h, c);
    fill_rect(x + w - 1, y, 1, h, c);
}

typedef struct { uint16_t m[3]; } gcol_t;
static const gcol_t *gtab;
static const uint8_t *gwid;
static uint8_t gfirst, gcount;

static void font_init(void) {
    const uint8_t *f = APTR(FONT);
    gfirst = f[0]; gcount = f[1];
    gwid = f + 3;
    gtab = (const gcol_t *)(f + 3 + gcount);
}

static int glyph(char ch) {
    if (!gtab) font_init();
    uint8_t c = (uint8_t)ch;
    if (c >= 'a' && c <= 'z') c -= 32;
    if (c < gfirst || c >= gfirst + gcount) c = '?';
    return c - gfirst;
}

int text_wn(const char *s, int n) {
    if (!gtab) font_init();
    int w = 0;
    for (; *s && n; s++, n--) w += gwid[glyph(*s)];
    return w ? w - 1 : 0;
}
int text_w(const char *s) { return text_wn(s, 9999); }
int text_w2(const char *s) { return text_w(s) * 2; }

extern uint8_t *tx_t1, *tx_t2;
void text_glyph(uint8_t *dst, const uint16_t *cols, unsigned n, uint8_t c);
void text_glyph2(uint8_t *dst, const uint16_t *cols, unsigned n, uint8_t c);
static uint8_t tx_space[768];
static int tx_colour = -1;

static void glyph_clip(int x, int y, const gcol_t *gc, uint8_t c, int sc,
                               void (*glyph_fn)(uint8_t *, const uint16_t *, unsigned, uint8_t)) {
    uint16_t win = 0, edge = 0;
    for (int r = 0; r < FONT_H; r++) {
        int a = y + r * sc, b = a + sc;
        if (a >= g_clip0 && b <= g_clip1) win |= (uint16_t)(1u << r);
        else if (b > g_clip0 && a < g_clip1) edge |= (uint16_t)(1u << r);
    }
    const uint8_t *bl = APTR(BLEND) + (c - 240) * 512;
    for (int i = 0; i < 8; i++) {
        uint16_t m[3] = { (uint16_t)(gc[i].m[0] & win), (uint16_t)(gc[i].m[1] & win), (uint16_t)(gc[i].m[2] & win) };
        uint16_t e[3] = { (uint16_t)(gc[i].m[0] & edge), (uint16_t)(gc[i].m[1] & edge), (uint16_t)(gc[i].m[2] & edge) };
        int px = x + i * sc;
        bool whole = px >= g_cx0 && px + sc <= g_cx1;
        if (whole && (m[0] | m[1] | m[2])) glyph_fn(hw_back + px * FBS + y, m, 1, c);
        for (int lvl = 0; lvl < 3; lvl++) {
            uint16_t mm = whole ? e[lvl] : (uint16_t)(gc[i].m[lvl] & (win | edge));
            if (!mm) continue;
            for (int k = 0; k < sc; k++) {
                int qx = px + k;
                if (qx < g_cx0 || qx >= g_cx1) continue;
                uint8_t *d = hw_back + qx * FBS;
                for (int r = 0; r < FONT_H; r++) {
                    if (!(mm >> r & 1)) continue;
                    for (int q = 0; q < sc; q++) {
                        int py = y + r * sc + q;
                        if (py < g_clip0 || py >= g_clip1) continue;
                        d[py] = lvl == 0 ? c : (lvl == 1 ? bl + 256 : bl)[d[py]];
                    }
                }
            }
        }
    }
}

static int txt_sc(int x, int y, const char *s, uint8_t c, int sc) {
    if (y >= g_clip1 || y + FONT_H * sc <= g_clip0) return x + text_w(s) * sc;
    bool clipped = y < g_clip0 || y + FONT_H * sc > g_clip1 || x < g_cx0 || x + (text_w(s) + 8) * sc > g_cx1;
    if (c != tx_colour) {
        if (!tx_t1) { tx_t1 = (uint8_t *)(((unsigned)tx_space + 255) & ~255u); tx_t2 = tx_t1 + 256; }
        const uint8_t *bl = APTR(BLEND) + (c - 240) * 512;
        memcpy(tx_t1, bl + 256, 256);
        memcpy(tx_t2, bl, 256);
        tx_colour = c;
    }
    void (*glyph_fn)(uint8_t *, const uint16_t *, unsigned, uint8_t) = sc == 1 ? text_glyph : text_glyph2;
    static gcol_t solid[8];
    uint8_t *col0 = hw_back + y;
    for (; *s; s++) {
        int g = glyph(*s);
        const gcol_t *gc = gtab + g * 8;
        if (g_solid) {
            for (int i = 0; i < 8; i++) { solid[i].m[0] = gc[i].m[0] | gc[i].m[1]; solid[i].m[1] = solid[i].m[2] = 0; }
            gc = solid;
        }
        if (!clipped) glyph_fn(col0 + x * FBS, gc[0].m, 8, c);
        else glyph_clip(x, y, gc, c, sc, glyph_fn);
        x += gwid[g] * sc;
    }
    return x;
}

int txt(int x, int y, const char *s, uint8_t c) { return txt_sc(x, y, s, c, 1); }
int txt2(int x, int y, const char *s, uint8_t c) { return txt_sc(x, y, s, c, 2); }
void txt_c(int cx, int y, const char *s, uint8_t c) { txt(cx - text_w(s) / 2, y, s, c); }
void txt2_c(int cx, int y, const char *s, uint8_t c) { txt2(cx - text_w2(s) / 2, y, s, c); }
int txt_sh(int x, int y, const char *s, uint8_t c) {
    txt_sc(x + 1, y + 1, s, C_BLACK, 1);
    return txt_sc(x, y, s, c, 1);
}
void txt_shc(int cx, int y, const char *s, uint8_t c) { txt_sh(cx - text_w(s) / 2, y, s, c); }
void txt2_shc(int cx, int y, const char *s, uint8_t c) {
    int x = cx - text_w2(s) / 2;
    txt_sc(x + 2, y + 2, s, C_BLACK, 2);
    txt_sc(x, y, s, c, 2);
}

void runs_map(const uint8_t *p, const uint8_t *tab) {
    int col = p[0], row = p[1] | p[2] << 8;
    int h = p[4] | p[5] << 8;
    p += 6;
    for (int r = 0; r < h; r++) {
        uint8_t *d = hw_back + (row + r) * FBS;
        bool vis = row + r >= g_cx0 && row + r < g_cx1;
        int y = col;
        for (;;) {
            uint8_t s = *p++;
            if (s == 0xFF) break;
            int n = *p++;
            y += s;
            if (vis) {
                int a = y < g_clip0 ? g_clip0 : y, b = y + n > g_clip1 ? g_clip1 : y + n;
                for (int k = a; k < b; k++) d[k] = tab[d[k]];
            }
            y += n;
        }
    }
}

const uint8_t *a_var[NUM_APPVARS];
uint16_t pal16[256];

static const struct { uint8_t var; uint16_t off; } sprite_refs[NUM_SPRITES] = SPRITE_REFS;
static const struct { uint8_t var; uint16_t off; } mask_refs[NUM_MASKS] = MASK_REFS;

const char *assets_load(void) {
    static const char *const names[NUM_APPVARS] = APPVAR_NAMES;
    static const uint24_t sizes[NUM_APPVARS] = APPVAR_SIZES;
    for (int i = 0; i < NUM_APPVARS; i++) {
        var_t *v = os_GetAppVarData(names[i], NULL);
        if (!v || v->size != sizes[i]) return names[i];
        a_var[i] = v->data;
    }
    (void)names;
    memcpy(pal16, APTR(PALETTE), 512);
    pal_used = PAL_USED;
    hw_pal(pal16, 0, 256);
    return NULL;
}

const uint8_t *spr(int id) { return a_var[sprite_refs[id].var] + sprite_refs[id].off; }
const uint8_t *msk(int id) { return a_var[mask_refs[id].var] + mask_refs[id].off; }

game_t G;

static uint32_t rs = 0x2545F491u;
void rnd_seed(uint32_t s) { rs ^= s * 2654435761u; if (!rs) rs = 1; }
uint16_t rnd(uint16_t n) {
    rs ^= rs << 13; rs ^= rs >> 17; rs ^= rs << 5;
    return (uint16_t)((uint16_t)(rs >> 8) % n);
}

static const uint8_t stage_hp[3] = { 2, 4, 6 };
static const uint8_t st_items[3] = { 0, 2, 4 };

static const uint8_t item_cap[NUM_IT] = { 0, 2, 2, 2, 1, 1 };

static void counts(uint8_t *live, uint8_t *blank) {
    uint8_t total = G.stage == 0 ? (uint8_t)(2 + rnd(4)) : (uint8_t)(3 + rnd(6));
    uint8_t lo = (uint8_t)((total + 2) / 3), hi = (uint8_t)(total - lo);
    if (lo > hi) lo = hi = total / 2;
    if (total == 2) lo = hi = 1;
    uint8_t l = (uint8_t)(lo + rnd((uint16_t)(hi - lo + 1)));
    *live = l;
    *blank = (uint8_t)(total - l);
}

int count_items(const uint8_t *slots) {
    int n = 0;
    for (int i = 0; i < 8; i++) n += slots[i] != IT_NONE;
    return n;
}

static int count_kind(const uint8_t *slots, uint8_t k) {
    int n = 0;
    for (int i = 0; i < 8; i++) n += slots[i] == k;
    return n;
}

static uint8_t draw_item(const uint8_t *slots) {
    uint8_t avail[NUM_IT], n = 0;
    for (uint8_t k = 1; k < NUM_IT; k++)
        if (count_kind(slots, k) < item_cap[k]) avail[n++] = k;
    return n ? avail[rnd(n)] : IT_NONE;
}

static const uint8_t item_value[NUM_IT] = { 0, 3, 2, 2, 3, 3 };
static int deal(const uint8_t *slots, uint8_t n, uint8_t *out) {
    int got = 0;
    for (int tries = 0; got < n && tries < 40; tries++) {
        uint8_t k = draw_item(slots);
        if (k == IT_NONE) break;
        bool bad = false;
        for (int i = 0; i < got; i++)
            if (out[i] == k || (out[i] == IT_GLASS && k == IT_SAW) || (out[i] == IT_SAW && k == IT_GLASS)) bad = true;
        int held = count_kind(slots, k);
        for (int i = 0; i < got; i++) held += out[i] == k;
        if (held >= item_cap[k]) bad = true;
        if (!bad) out[got++] = k;
    }
    return got;
}

static int hand_value(const uint8_t *h, int n) {
    int v = 0;
    for (int i = 0; i < n; i++) v += item_value[h[i]];
    return v;
}

static uint8_t shell_pop(void) {
    uint8_t s = G.seq[0];
    memmove(G.seq, G.seq + 1, 7);
    G.nseq--;
    G.ejected++;
    return s;
}

static void heal(bool dealer, int8_t amount) {
    int8_t *hp = dealer ? &G.hp_d : &G.hp_p;
    if (dealer ? G.wire_d : G.wire_p) return;
    *hp += amount;
    if (*hp > G.hp_max) *hp = G.hp_max;
}

static void wires(void) {
    if (G.stage != 2) return;
    if (G.hp_d <= 2 && !G.wire_d) { G.wire_d = true; pr_cut(WHO_DEALER); }
    if (G.hp_p <= 2 && !G.wire_p) { G.wire_p = true; pr_cut(WHO_PLAYER); }
}

static void d_remove(uint8_t slot) {
    G.it_d[slot] = IT_NONE;
    for (uint8_t i = 0; i < G.n_order; i++)
        if (G.d_order[i] == slot) {
            memmove(G.d_order + i, G.d_order + i + 1, (size_t)(G.n_order - i - 1));
            G.n_order--;
            break;
        }
}

static const uint8_t items_2p[3] = { 0, 2, 4 };
static void grab_items(void) {
    uint8_t n = G.two_p ? items_2p[G.stage] : st_items[G.stage];
    if (!G.items_told && !G.two_p) {
        pr_say("LET'S MAKE THIS A LITTLE MORE INTERESTING...", 3000);
        G.items_told = true;
        char b[24] = "0 ITEMS EACH.";
        b[0] = (char)('0' + n);
        pr_say(b, 2500);
        pr_say("MORE ITEMS BEFORE EVERY LOAD.", 2500);
    }

    uint8_t hp_items[8], hd_items[8];
    uint8_t room_p = (uint8_t)(8 - count_items(G.it_p)), room_d = (uint8_t)(8 - count_items(G.it_d));
    int np = deal(G.it_p, n < room_p ? n : room_p, hp_items), nd = 0;
    for (int tries = 0; tries < 30; tries++) {
        nd = deal(G.it_d, n < room_d ? n : room_d, hd_items);
        int dv = hand_value(hd_items, nd) - hand_value(hp_items, np);
        if (dv >= -1 && dv <= 1) break;
    }
    for (int i = 0; i < np; i++) {
        uint8_t slot = 0;
        pr_p_grab(hp_items[i], &slot);
        G.it_p[slot] = hp_items[i];
    }
    if (np < n && count_items(G.it_p) == 8) pr_full();

    for (int i = 0; i < nd; i++) {
        uint8_t free[8], nf = 0;
        for (uint8_t s2 = 0; s2 < 8; s2++) if (!G.it_d[s2]) free[nf++] = s2;
        uint8_t s2 = free[rnd(nf)];
        G.it_d[s2] = hd_items[i];
        G.d_order[G.n_order++] = s2;
    }
    pr_d_grab();
}

static void new_load(void) {
    if (G.d_cuffed || G.p_cuffed) {
        G.d_cuffed = G.d_break = G.p_cuffed = G.p_break = false;
        pr_uncuff();
    }
    if (G.stage == 2 && G.load == 0 && !G.two_p) {
        if (!G.read_final) {
            pr_say("LONG LAST, WE ARRIVE AT THE FINAL SHOWDOWN.", 4000);
            pr_say("NO MORE DEFIBRILLATORS. NO MORE BLOOD TRANSFUSIONS.", 4000);
            pr_say("NOW, ME AND YOU, WE ARE DANCING ON THE EDGE OF LIFE AND DEATH.", 4800);
            G.read_final = true;
        } else {
            pr_say("BETTER NOT MISS THIS TIME.", 3000);
        }
    }
    if (G.two_p ? items_2p[G.stage] : st_items[G.stage]) grab_items();

    uint8_t live, blank;
    counts(&live, &blank);
    G.lives = live; G.blanks = blank;
    G.nseq = live + blank;

    uint8_t show[8];
    for (uint8_t i = 0; i < G.nseq; i++) show[i] = i < live;
    for (uint8_t i = G.nseq - 1; i > 0; i--) { uint8_t j = (uint8_t)rnd(i + 1), t = show[i]; show[i] = show[j]; show[j] = t; }
    memcpy(G.seq, show, 8);
    for (uint8_t i = G.nseq - 1; i > 0; i--) { uint8_t j = (uint8_t)rnd(i + 1), t = G.seq[i]; G.seq[i] = G.seq[j]; G.seq[j] = t; }

    char text[40];
    const char *shown = NULL;
    unsigned ms;
    if (!G.shows) {
        char *p = text;
        *p++ = (char)('0' + live);
        strcpy(p, live == 1 ? " LIVE ROUND. " : " LIVE ROUNDS. ");
        p += strlen(p);
        *p++ = (char)('0' + blank);
        strcpy(p, blank == 1 ? " BLANK." : " BLANKS.");
        shown = text;
        ms = 2500;
    } else if (G.stage == 2 && !G.two_p && !G.drill_shown) {
        shown = "YOU KNOW THE DRILL."; G.drill_shown = true; ms = 1800;
    } else {
        int t = 1500 - 210 * (G.shows - 1);
        ms = (unsigned)(t < 450 ? 450 : t);
    }
    if (G.shows < 255) G.shows++;
    pr_shells(show, G.nseq, shown, ms);

    if (G.load_talks < 3 && !G.two_p) {
        pr_say(G.load_talks & 1 ? "THEY ENTER THE CHAMBER IN A HIDDEN SEQUENCE."
                                    : "I INSERT THE SHELLS IN AN UNKNOWN ORDER.", 3000);
        G.load_talks++;
    }
    pr_load(G.nseq);
    if (G.stage == 0 && G.load == 0 && !G.read_intro && !G.two_p) {
        static const char *const intro[] = {
            "THE RULES ARE SIMPLE.",
            "WE TAKE TURNS WITH THE SHOTGUN.",
            "PICK IT UP. POINT IT AT ME, OR AT YOURSELF.",
            "A LIVE SHELL TAKES ONE CHARGE.",
            "SHOOT YOURSELF WITH A BLANK...",
            "...AND YOU KEEP YOUR TURN.",
            "SHOOT ME WITH A BLANK AND YOUR TURN IS OVER.",
            "WHEN YOUR CHARGES RUN OUT...",
            "...YOU LOSE.",
        };
        static const uint16_t dur[] = { 1900, 3000, 3000, 3000, 3000, 3700, 3700, 3700, 2500 };
        for (int i = 0; i < 9; i++) pr_say(intro[i], dur[i]);
        G.read_intro = true;
    }
    G.load++;
}

enum { NX_PLAYER, NX_DEALER, NX_NEWLOAD, NX_WIN, NX_LOSE };

static int end_turn(bool again) {
    if (G.sawed) { G.sawed = false; G.dmg = 1; pr_regrow(); }
    if (!G.nseq) return NX_NEWLOAD;
    return again ? NX_PLAYER : NX_DEALER;
}

static int p_turn(void) {
    for (;;) {
        int a = pr_p_turn();
        if (a < 8) {
            uint8_t k = G.it_p[a];
            int info = 0;
            if (k == IT_CUFFS && G.d_cuffed) continue;
            if (k == IT_SAW && G.sawed) continue;
            G.it_p[a] = IT_NONE;
            switch (k) {
            case IT_GLASS: info = G.seq[0]; break;
            case IT_CIGS: G.cigs++; heal(false, 1); break;
            case IT_BEER: G.beer_ml += 330; info = shell_pop(); break;
            case IT_CUFFS: G.d_cuffed = true; G.d_break = false; break;
            case IT_SAW: G.sawed = true; G.dmg = 2; break;
            }
            pr_p_item((uint8_t)a, k, info);
            if (k == IT_CIGS) pr_hp();
            if (k == IT_BEER && !G.nseq) return NX_NEWLOAD;
            continue;
        }
        bool live = G.seq[0];
        bool at_dealer = a == ACT_SHOOT_DEALER;
        shell_pop();
        if (live) G.shots++;
        if (at_dealer) {
            if (live) {
                G.hp_d -= (int8_t)G.dmg;
                if (G.hp_d < 0) G.hp_d = 0;
            }
            pr_shot(WHO_PLAYER, WHO_DEALER, live, live && !G.hp_d);
            if (live) {
                G.d_crushed = true;
                if (!G.hp_d) return NX_WIN;
                pr_hp();
                wires();
            }
            return end_turn(false);
        }
        if (live) {
            G.hp_p -= (int8_t)G.dmg;
            if (G.hp_p < 0) G.hp_p = 0;
        }
        pr_shot(WHO_PLAYER, WHO_PLAYER, live, live && !G.hp_p);
        if (live) {
            if (!G.hp_p) return NX_LOSE;
            pr_hp();
            wires();
            return end_turn(false);
        }
        return end_turn(true);
    }
}

static int p2_turn(void) {
    for (;;) {
        if (!G.nseq) return NX_NEWLOAD;
        int a = pr_p2_turn();
        if (a < 8) {
            uint8_t k = G.it_d[a];
            int info = 0;
            if (k == IT_CUFFS && G.p_cuffed) continue;
            if (k == IT_SAW && G.sawed) continue;
            d_remove((uint8_t)a);
            switch (k) {
            case IT_GLASS: info = G.seq[0]; break;
            case IT_CIGS: heal(true, 1); break;
            case IT_BEER: info = shell_pop(); break;
            case IT_CUFFS: G.p_cuffed = true; G.p_break = false; break;
            case IT_SAW: G.sawed = true; G.dmg = 2; break;
            }
            pr_d_item((uint8_t)a, k, info);
            if (k == IT_CIGS) pr_hp();
            if (k == IT_BEER && !G.nseq) return NX_NEWLOAD;
            continue;
        }
        bool live = G.seq[0];
        bool at_p1 = a == ACT_SHOOT_DEALER;
        shell_pop();
        if (live) G.shots++;
        if (at_p1) {
            if (live) { G.hp_p -= (int8_t)G.dmg; if (G.hp_p < 0) G.hp_p = 0; }
            pr_shot(WHO_DEALER, WHO_PLAYER, live, live && !G.hp_p);
            if (live) {
                if (!G.hp_p) return NX_LOSE;
                pr_hp();
                wires();
            }
            return end_turn(true);
        }
        if (live) { G.hp_d -= (int8_t)G.dmg; if (G.hp_d < 0) G.hp_d = 0; }
        pr_shot(WHO_DEALER, WHO_DEALER, live, live && !G.hp_d);
        if (live) {
            if (!G.hp_d) return NX_WIN;
            pr_hp();
            wires();
            return end_turn(true);
        }

        if (!G.nseq) return end_turn(true);
    }
}

static bool d_choice(void) {
    uint8_t want = IT_NONE, want_slot = 0;
    bool loop_done = false;
    if (G.nseq == 1) {
        G.d_known = G.seq[0] ? KNOWN_LIVE : KNOWN_BLANK;
        G.d_target = G.seq[0] ? TGT_PLAYER : TGT_SELF;
        G.d_knows = true;
    }
    for (uint8_t i = 0; i < G.n_order; i++) {
        uint8_t s = G.d_order[i], k = G.it_d[s];
        if (k == IT_GLASS && !G.d_knows && G.nseq != 1) {
            want = k; want_slot = s;
            G.d_known = G.seq[0] ? KNOWN_LIVE : KNOWN_BLANK;
            G.d_target = G.seq[0] ? TGT_PLAYER : TGT_SELF;
            G.d_knows = true;
            break;
        }
        if (k == IT_CIGS && G.hp_d < G.hp_max) { want = k; want_slot = s; break; }
        if (k == IT_BEER && G.d_known != KNOWN_LIVE && G.nseq != 1) { want = k; want_slot = s; break; }
        if (k == IT_CUFFS && !G.p_cuffed && G.nseq != 1) {
            want = k; want_slot = s;
            G.p_cuffed = true;
            break;
        }
        if (k == IT_SAW && !G.sawed && G.d_known == KNOWN_LIVE) {
            want = k; want_slot = s;
            G.d_sawing = true;
            G.sawed = true; G.dmg = 2;
            break;
        }
    }
    if (want == IT_NONE) loop_done = true;
    int saw_slot = -1;
    for (uint8_t i = 0; i < G.n_order; i++)
        if (G.it_d[G.d_order[i]] == IT_SAW) { saw_slot = G.d_order[i]; break; }
    if (loop_done && !G.d_sawing && saw_slot >= 0 && !G.sawed && G.d_known != KNOWN_BLANK) {
        if (rnd(2) == 0) G.d_target = TGT_SELF;
        else {
            G.d_target = TGT_PLAYER;
            want = IT_SAW; want_slot = (uint8_t)saw_slot;
            G.d_sawing = true;
            G.sawed = true; G.dmg = 2;
        }
    }
    if (want == IT_NONE) return false;

    int info = 0;
    d_remove(want_slot);
    switch (want) {
    case IT_GLASS: info = G.seq[0]; break;
    case IT_CIGS: heal(true, 1); break;
    case IT_BEER: info = shell_pop(); break;
    case IT_CUFFS: G.p_break = false; break;
    }
    pr_d_item(want_slot, want, info);
    if (want == IT_CIGS) pr_hp();
    return true;
}

static int find_item(uint8_t k) {
    for (uint8_t i = 0; i < G.n_order; i++)
        if (G.it_d[G.d_order[i]] == k) return G.d_order[i];
    return -1;
}

static bool d_use(uint8_t want, int slot) {
    int info = 0;
    d_remove((uint8_t)slot);
    switch (want) {
    case IT_GLASS: info = G.seq[0]; G.d_knows = true; G.d_known = G.seq[0] ? KNOWN_LIVE : KNOWN_BLANK; break;
    case IT_CIGS: heal(true, 1); break;
    case IT_BEER: info = shell_pop(); G.d_knows = false; G.d_known = KNOWN_NONE; break;
    case IT_CUFFS: G.p_cuffed = true; G.p_break = false; break;
    case IT_SAW: G.d_sawing = true; G.sawed = true; G.dmg = 2; break;
    }
    pr_d_item((uint8_t)slot, want, info);
    if (want == IT_CIGS) pr_hp();
    return true;
}

static bool d_choice_hard(void) {
    int live = 0;
    for (uint8_t i = 0; i < G.nseq; i++) live += G.seq[i];
    int blank = G.nseq - live;
    if (!G.d_knows && (live == 0 || blank == 0)) {
        G.d_knows = true;
        G.d_known = live ? KNOWN_LIVE : KNOWN_BLANK;
    }
    int s;
    if (G.hp_d < G.hp_max && !G.wire_d && (s = find_item(IT_CIGS)) >= 0) return d_use(IT_CIGS, s);
    if (!G.d_knows && G.nseq > 1 && (s = find_item(IT_GLASS)) >= 0) return d_use(IT_GLASS, s);

    int p6 = G.d_knows ? (G.d_known == KNOWN_LIVE ? 6 : 0) : live * 6 / G.nseq;
    if (!G.d_knows && G.nseq > 1 && p6 < 4 && (s = find_item(IT_BEER)) >= 0) return d_use(IT_BEER, s);
    if (p6 >= 3) {
        if (!G.p_cuffed && G.nseq > 1 && (s = find_item(IT_CUFFS)) >= 0) return d_use(IT_CUFFS, s);
        if (!G.sawed && p6 >= 4 && (s = find_item(IT_SAW)) >= 0) return d_use(IT_SAW, s);
        G.d_target = TGT_PLAYER;
    } else {
        G.d_target = TGT_SELF;
    }
    return false;
}

static int d_turn(void) {
    G.d_sawing = false;
    for (;;) {
        if (!G.nseq) return NX_NEWLOAD;
        while (G.hard ? d_choice_hard() : d_choice())
            if (!G.nseq) return NX_NEWLOAD;
        uint8_t tgt = G.d_target ? G.d_target : (rnd(2) ? TGT_PLAYER : TGT_SELF);
        G.d_target = TGT_NONE; G.d_known = KNOWN_NONE; G.d_knows = false;
        bool live = G.seq[0];
        shell_pop();
        if (live) G.shots++;
        if (tgt == TGT_SELF) {
            if (live) {
                G.hp_d -= (int8_t)G.dmg;
                if (G.hp_d < 0) G.hp_d = 0;
            }
            pr_shot(WHO_DEALER, WHO_DEALER, live, live && !G.hp_d);
            if (live) {
                G.d_crushed = true;
                if (!G.hp_d) return NX_WIN;
                pr_hp();
                wires();
                return end_turn(true);
            }

            if (!G.nseq) return end_turn(true);
            G.d_sawing = false;
            continue;
        }
        if (live) {
            G.hp_p -= (int8_t)G.dmg;
            if (G.hp_p < 0) G.hp_p = 0;
        }
        pr_shot(WHO_DEALER, WHO_PLAYER, live, live && !G.hp_p);
        if (live) {
            if (!G.hp_p) return NX_LOSE;
            pr_hp();
            wires();
        }
        return end_turn(true);
    }
}

static int play_stage(void) {
    G.load = 0;
    G.hp_max = (int8_t)stage_hp[G.stage];
    G.hp_p = G.hp_d = G.hp_max;
    G.wire_p = G.wire_d = false;
    G.sawed = false; G.dmg = 1;
    G.p_cuffed = G.p_break = G.d_cuffed = G.d_break = false;
    if (count_items(G.it_p) || count_items(G.it_d)) pr_clear();
    memset(G.it_p, 0, 8); memset(G.it_d, 0, 8); G.n_order = 0;
    G.d_known = KNOWN_NONE; G.d_target = TGT_NONE; G.d_knows = false;
    pr_round();
    pr_hp_boot();
    int nx = NX_NEWLOAD;
    for (;;) {
        switch (nx) {
        case NX_NEWLOAD:
            new_load();

            nx = G.two_p && ((G.first + G.nloads++) & 1) ? NX_DEALER : NX_PLAYER;
            break;
        case NX_PLAYER:
            if (G.p_cuffed) {
                if (!G.p_break) { pr_cuffs(WHO_PLAYER, false); G.p_break = true; nx = NX_DEALER; break; }
                pr_cuffs(WHO_PLAYER, true);
                G.p_cuffed = G.p_break = false;
            }
            nx = p_turn();
            break;
        case NX_DEALER:
            if (G.d_cuffed) {
                if (!G.d_break) { pr_cuffs(WHO_DEALER, false); G.d_break = true; nx = NX_PLAYER; break; }
                pr_cuffs(WHO_DEALER, true);
                G.d_cuffed = false;
            }
            nx = G.two_p ? p2_turn() : d_turn();
            break;
        default:
            return nx;
        }
    }
}

void game_new(void) {
    char name[7], name2[7];
    bool hard = G.hard, two = G.two_p;
    memcpy(name, G.name, 7);
    memcpy(name2, G.name2, 7);
    memset(&G, 0, sizeof G);
    memcpy(G.name, name, 7);
    memcpy(G.name2, name2, 7);
    G.hard = hard;
    G.two_p = two;
    G.doors = 2;
}

int game_run(void) {
    pr_arrive();
    if (G.two_p) {
        G.first = (uint8_t)rnd(2);
        for (;;) {
            int r = play_stage();
            uint8_t w = r == NX_WIN ? WHO_PLAYER : WHO_DEALER;
            if (w == WHO_PLAYER) G.wins_p++; else G.wins_d++;
            if (G.wins_p == 2 || G.wins_d == 2) { pr_match_end(w); return 1; }
            pr_round_end(w);
            G.stage++;
        }
    }
    for (;;) {
        int r = play_stage();
        if (r == NX_WIN) {
            G.stage++;
            if (G.stage == 3) { pr_ending(); return 1; }
            pr_won();
            continue;
        }

        pr_death(G.stage == 2);
        G.doors += 2;
        G.d_crushed = false;
        G.drill_shown = false;
        pr_arrive();
        pr_say(G.stage == 2 ? "..." : "WELCOME BACK.", 2300);
    }
}

