#define clip_kf ((const kf_t *)APTR(CLIPKF))
static const uint16_t clip_first[NUM_CLIPS] = CLIP_START;
static struct {
    int id;
    tick_t t0;
    uint16_t i;
    bool hold, done;
    int dx, dy;
    uint8_t slow;
} CL = { .id = -1 };

static const kf_t *clip_cur(void) { return CL.id < 0 ? NULL : clip_kf + clip_first[CL.id] + CL.i; }

static void clip_rows(int *y0, int *y1) {
    const kf_t *kf = clip_cur();
    *y0 = 240; *y1 = 0;
    if (!kf || kf->spr >= KF_END) return;
    const uint8_t *p = spr(kf->spr);
    *y0 = p[0] + CL.dy - 1; *y1 = p[0] + p[3] + CL.dy + 1;
}

static void clip_cols(int *x0, int *x1) {
    const kf_t *kf = clip_cur();
    *x0 = 320; *x1 = 0;
    if (!kf || kf->spr >= KF_END) return;
    const uint8_t *p = spr(kf->spr);
    int r = p[1] | p[2] << 8;
    *x0 = r + CL.dx - 1; *x1 = r + (p[4] | p[5] << 8) + CL.dx + 1;
}

static struct { int id; tick_t t0; uint16_t i; uint8_t slow, tail; bool hold, held; int cue; uint16_t cue_ms; } CL2 = { -1, 0, 0, 0, 0, 0, 0, -1, 0 };
static const kf_t *clip2_cur(void) { return CL2.id < 0 ? NULL : clip_kf + clip_first[CL2.id] + CL2.i; }
static void clip2_start(int id, uint8_t slow) { CL2.id = id; CL2.t0 = hw_ticks(); CL2.i = 0; CL2.slow = slow ? slow : 1; CL2.hold = CL2.held = false; }

static void clip2_cue(int id, unsigned ms, bool live) { CL2.cue = id; CL2.cue_ms = (uint16_t)ms; V.eject_next = live ? 2 : 1; }
static void clip2_clear(void) { if (CL2.id >= 0) { CL2.id = -1; CL2.tail = 2; V.dirty = true; } CL2.cue = -1; }
static void clip2_update(void) {
    if (CL2.id < 0 || CL2.held) return;
    const kf_t *k = clip_kf + clip_first[CL2.id];
    unsigned long t = ((unsigned long)((hw_now - CL2.t0) & 0xFFFFFF) * 125u) >> 12;
    t /= CL2.slow;
    uint16_t i0 = CL2.i;
    while (k[CL2.i].spr != KF_END && k[CL2.i + 1].t <= t) CL2.i++;
    if (k[CL2.i].spr == KF_END) {
        if (CL2.hold && CL2.i) { CL2.i--; CL2.held = true; }
        else CL2.id = -1;
        CL2.tail = 2;
    }
    if (CL2.i != i0 || CL2.id < 0) V.dirty = true;
}

static void clip_update(void) {
    if (CL.id < 0 || CL.done) return;
    const kf_t *k = clip_kf + clip_first[CL.id];
    unsigned long t = ((unsigned long)((hw_now - CL.t0) & 0xFFFFFF) * 125u) >> 12;
    if (CL.slow > 1) t /= CL.slow;
    if (CL2.cue >= 0 && t >= CL2.cue_ms) {
        clip2_start(CL2.cue, 1); CL2.hold = true; CL2.cue = -1;
        V.eject_lbl = V.eject_next; V.eject_t0 = hw_now;
    }
    while (k[CL.i].spr != KF_END && k[CL.i + 1].t <= t) CL.i++;
    if (k[CL.i].spr == KF_END) {
        CL.done = true;
        if (CL.i) CL.i--;
    }
    const kf_t *a = k + CL.i, *b = a + 1;
    if (a->cam <= PAN_N) {
        int cam = a->cam;
        if (!CL.done && b->cam <= PAN_N && b->t > a->t)
            cam += (int)((long)(b->cam - a->cam) * (long)(t - a->t) / (long)(b->t - a->t));
        V.cam = cam;
    }
}

static int wrap(const char *s, char lines[3][64]) {
    int nl = 0;
    const char *p = s;
    while (*p && nl < 3) {
        int best = 0, i = 0, w = 0;
        while (p[i] && i < 63) {
            w += text_wn(p + i, 1) + 1;
            if (w - 1 > 300) break;
            if (p[i] == ' ') best = i;
            i++;
        }
        if (!p[i] || i >= 63) best = i;
        if (best == 0) best = i;
        memcpy(lines[nl], p, (size_t)best); lines[nl][best] = 0;
        p += best;
        while (*p == ' ') p++;
        nl++;
    }
    return nl;
}

static void txt_wrap(const char *s, int len, int cy, uint8_t col) {
    char lines[3][64];
    int nl = wrap(s, lines);
    int y = cy - nl * (FONT_H + 2) / 2;
    int off = 0;
    for (int l = 0; l < nl; l++) {
        int ll = (int)strlen(lines[l]);
        char buf[64];
        int k = len - off;
        if (k < 0) k = 0;
        if (k > ll) k = ll;
        int x = 160 - text_w(lines[l]) / 2;
        memcpy(buf, lines[l], (size_t)k); buf[k] = 0;
        txt_sh(x, y, buf, col);
        off += ll + 1;
        y += FONT_H + 2;
    }
}

static void draw_hp(void) {
    static const int8_t sh1[HV_SLOTS][2] = HV_NAME_SHIFT, sh2[HV_SLOTS][2] = HV_NAME2_SHIFT;
    draw_sprite(spr(S_HV_BG));
    bool blink = (hw_now >> 12) & 1;
    for (int i = 0; i < V.hp_d && i < 6; i++)
        if (!(V.hp_d == 1 && blink)) draw_sprite(spr(S_HV_D1 + i));
    for (int i = 0; i < V.hp_p && i < 6; i++)
        if (!(V.hp_p == 1 && blink)) draw_sprite(spr(S_HV_P1 + i));
    if (!G.two_p) draw_runs(msk(M_HV_DEALER), C_GREEN, 0, 0, 240);
    else {
        int n2 = (int)strlen(G.name2);
        for (int i = 0; i < n2 && i < HV_SLOTS; i++)
            if (G.name2[i] >= 'A' && G.name2[i] <= 'Z') runs_at(msk(HV_NAME2_MASK(G.name2[i])), C_GREEN, sh2[i][0], sh2[i][1]);
    }
    int n = (int)strlen(G.name);
    for (int i = 0; i < n; i++) {
        char c = G.name[i];
        if (c >= 'A' && c <= 'Z' && n - 1 - i < HV_SLOTS) runs_at(msk(HV_NAME_MASK(c)), C_GREEN, sh1[n - 1 - i][0], sh1[n - 1 - i][1]);
    }
}

static void draw_sv(void) {
    draw_sprite(spr(S_SV_BG));
    for (int i = 0; i < V.nshow; i++) draw_sprite(spr(V.sv_order[i] ? S_SV_L0 + i : S_SV_B0 + i));
}

static void draw_in(int view, int id, int c0, int c1) {
    if (id == (int)NOSPR) return;
    const uint8_t *s = spr(id);
    int cy = s[0] + s[3] / 2, cx = (s[1] | s[2] << 8) + (s[4] | s[5] << 8) / 2;
    int dx, dy;
    pan_place(V.cam, view, cx, cy, &dx, &dy);
    g_ox += dx;
    draw_lz(s, dy, c0, c1);
    g_ox -= dx;
}

static void mask_in(int id, uint8_t c, int seam) {
    if (id == NOMASK) return;
    const uint8_t *m = msk(id);
    int cy = m[0] + m[3] / 2;
    int dy = pan_row(V.cam, VIEW_HOME, cy) - cy;
    draw_runs(m, c, dy, seam, 240);
}

static void placed(int v, int id, int *x, int *y) {
    const uint8_t *s = spr(id);
    int cy = s[0] + s[3] / 2, cx = (s[1] | s[2] << 8) + (s[4] | s[5] << 8) / 2, dx, dy;
    pan_place(V.cam, v, cx, cy, &dx, &dy);
    *x = cx + dx; *y = cy + dy;
}

static struct { uint16_t hs, es, id; int16_t key, ox, oy; } tb[24];
static uint8_t tb_ord[24];

static __attribute__((noinline)) void draw_table(int v, bool turning, int c0, int c1, uint8_t fl) {
    static const uint16_t ht[4][13] = HT_SPRITES;
    int n = 0, ve = SV(VIEW_ENEMY), vh = SV(v);
    if (!V.view && ht[vh][0] != NOSPR) {
        tb[n].hs = ht[vh][0]; tb[n++].es = ht[ve][0];
        for (int i = 0; i < V.hp_d && i < 6; i++) { tb[n].hs = ht[vh][1 + i]; tb[n++].es = ht[ve][1 + i]; }
        for (int i = 0; i < V.hp_p && i < 6; i++) { tb[n].hs = ht[vh][7 + i]; tb[n++].es = ht[ve][7 + i]; }
    }
    int nht = n;
    for (int s = 0; s < 16; s++) {
        uint8_t k = s < 8 ? G.it_d[s] : G.it_p[s - 8];
        int slot = s < 8 ? 8 + s : s - 8;
        if (k) { tb[n].hs = item_spr[vh][k][slot]; tb[n++].es = item_spr[ve][k][slot]; }
    }
    if (V.gun_down && !(fl & HIDE_GUN)) {
        if (fl & GUN_REST) { tb[n].hs = G.sawed ? S_HOME_SHOTGUN_SAWED : S_HOME_SHOTGUN; tb[n++].es = NOSPR; }
        else { tb[n].hs = gun_spr(v); tb[n++].es = gun_spr(VIEW_ENEMY); }
    }
    for (int i = 0; i < n; i++) {
        tb_ord[i] = (uint8_t)i;
        tb[i].ox = tb[i].oy = 0;
        tb[i].id = tb[i].hs;
        tb[i].key = -1000;
        if (tb[i].hs == NOSPR) continue;
        int x0, y0, h = spr(tb[i].hs)[3];
        placed(v, tb[i].hs, &x0, &y0);
        int w = turning && tb[i].es != NOSPR ? pan_blend(V.cam, y0) : 0;
        int x = x0, y = y0;
        if (w) {
            int x1, y1;
            placed(VIEW_ENEMY, tb[i].es, &x1, &y1);
            x = x0 + (x1 - x0) * w / 256; y = y0 + (y1 - y0) * w / 256;
            if (w >= 128) { tb[i].id = tb[i].es; x0 = x1; y0 = y1; h = spr(tb[i].es)[3]; }
        }
        tb[i].ox = (int16_t)(x - x0); tb[i].oy = (int16_t)(y - y0);
        tb[i].key = (int16_t)(y + h / 2);
    }
    for (int i = nht + 1; i < n; i++) {
        uint8_t o = tb_ord[i];
        int j = i;
        while (j > nht && tb[tb_ord[j - 1]].key > tb[o].key) { tb_ord[j] = tb_ord[j - 1]; j--; }
        tb_ord[j] = o;
    }
    for (int k = 0; k < n; k++) {
        int i = tb_ord[k];
        if (tb[i].id == NOSPR) continue;
        g_ox += tb[i].ox; g_oy += tb[i].oy;
        draw_in(tb[i].id == tb[i].hs ? v : VIEW_ENEMY, tb[i].id, c0, c1);
        g_ox -= tb[i].ox; g_oy -= tb[i].oy;
    }
}

static uint8_t fx_mode;

static uint16_t pal_base[256];
static int pal_key = -1;
static bool pal_hold;
static void pal_sync(bool full) {
    int key = 255;
    (void)full;
    if (key == pal_key) return;
    pal_key = key;
    memcpy(pal_base, pal16, sizeof pal_base);
    if (key != 255) {
        const uint16_t *k = (const uint16_t *)APTR(PALK);
        int i = key >> 3, f = key & 7;
        const uint16_t *a = k + i * PAL_USED, *b = k + (i < PALK_N - 1 ? i + 1 : i) * PAL_USED;
        for (int e = 0; e < PAL_USED; e++) {
            uint16_t ca = a[e], cb = b[e];
            if (!f || ca == cb) { pal_base[e] = ca; continue; }
            int r = ((ca >> 10) & 31) * (8 - f) + ((cb >> 10) & 31) * f;
            int g = (((ca >> 5) & 31) << 1 | ca >> 15) * (8 - f) + (((cb >> 5) & 31) << 1 | cb >> 15) * f;
            int bl = (ca & 31) * (8 - f) + (cb & 31) * f;
            r = (r + 4) >> 3; g = (g + 4) >> 3; bl = (bl + 4) >> 3;
            pal_base[e] = (uint16_t)(r << 10 | (g >> 1) << 5 | bl | (g & 1) << 15);
        }
    }
    if (!fx_mode && !pal_hold) hw_pal_next(pal_base);
}

static void compose(void) {
    const kf_t *kf = V.view ? NULL : clip_cur(), *kf2 = V.view ? NULL : clip2_cur();
    pal_sync(kf && kf->cam == CAM_FULL);
    if (kf2 && kf2->cam != V.cam) kf2 = NULL;
    uint8_t fl = (kf ? kf->flags : 0) | (kf2 && kf2->spr < KF_END ? kf2->flags : 0);
    bool full = V.view || (kf && kf->cam == CAM_FULL);
    int seam = pan_seam(V.cam);
    int sx = g_ox, sy = g_oy;
    if (V.blackout) goto ui;
    if (V.view == VW_HEALTH) draw_hp();
    else if (V.view == VW_SHELLS) draw_sv();
    else if (full) draw_sprite(spr(kf->spr));
    else draw_bg_pan(V.cam);
    hw_sample();

    bool turning = !full && V.cam > 0 && V.cam < PAN_N;
    for (int v = 0; v < 2 && !full; v++) {
        if (v == VIEW_HOME && seam >= 240) continue;
        if (v == VIEW_ENEMY && seam <= 0) continue;
        int c0 = turning ? 0 : v == VIEW_HOME ? seam : 0, c1 = turning ? 240 : v == VIEW_HOME ? 240 : seam;
        if (v == VIEW_ENEMY && !V.d_away) {
            if (!(fl & HIDE_HEAD)) draw_in(v, g_seat ? S_ENEMY2_DEALER : S_ENEMY_DEALER, c0, c1);

            bool far_cuffed = g_seat ? G.p_cuffed : G.d_cuffed;
            if (!(fl & HIDE_HANDS)) draw_in(v, far_cuffed ? clip_kf[clip_first[CLIP_D_CUFFED_IDLE]].spr : g_seat ? S_ENEMY2_HANDS : S_ENEMY_HANDS, c0, c1);
        }
        if (turning && v == VIEW_ENEMY) continue;
        draw_table(v, turning, c0, c1, fl);
    }
    if (kf2 && !full && kf2->spr < KF_END) draw_sprite(spr(kf2->spr));
    if (kf && !full && kf->spr != KF_NONE) {
        g_ox += CL.dx; g_oy += CL.dy;
        draw_sprite(spr(kf->spr));
    }
    g_ox = g_oy = 0;
    if (V.splat >= 0) {
        const uint8_t *add = APTR(ADDRED);
        for (int lvl = 1; lvl <= 3; lvl++) {
            int t = lvl - V.sp_fade;
            if (t >= 1) runs_map(msk(M_BLOOD0_1 + V.splat * 3 + lvl - 1), add + (t - 1) * 256);
        }
    }
    if (V.aiming && !V.view && !G.two_p) {
        mask_in(M_TXT_DEALER, V.target == 0 ? C_WHITE : C_MGREY, seam);
        mask_in(M_TXT_YOU, V.target == 1 ? C_WHITE : C_MGREY, seam);
    }
    if (V.aiming && G.two_p) {
        char b[24] = "SHOOT ";
        strcat(b, side ? G.name : G.name2);
        g_solid = true;
        txt2_shc(160, 164, b, V.target == 0 ? C_WHITE : C_DGREY);
        txt2_shc(160, 196, "SHOOT YOURSELF", V.target == 1 ? C_WHITE : C_DGREY);
        g_solid = false;
    }
    if (V.sel >= 0 && !V.aiming && !V.view && !ol_overlay) {
        if (V.sel == 8) mask_in(gun_ol(), C_WHITE, seam);
        else if (my_items()[V.sel]) mask_in(item_ol[OLSET][my_items()[V.sel]][V.sel], C_WHITE, seam);
    }
    if (V.held_item) {
        if (V.held_item == IT_GLASS || V.held_item == IT_BEER) {
            uint8_t c = V.held_live ? C_RED : C_BLUE;
            fill_rect(118, 94, 84, 26, C_BLACK);
            fill_rect(120, 96, 64, 22, c);
            fill_rect(184, 96, 16, 22, C_YELLOW);
            txt_shc(160, 124, V.held_live ? "LIVE" : "BLANK", C_WHITE);
        }
    }
ui:
    g_ox = g_oy = 0;
    if (V.eject_lbl && !V.blackout) {
        bool lv = V.eject_lbl == 2;
        const char *w = lv ? "LIVE" : "BLANK";
        uint8_t c = lv ? C_RED : C_BLUE;
        int iw = 30, x = 160 - (iw + 8 + text_w2(w)) / 2, y = 166;
        txt_shc(160, y - 17, "SHELL EJECTED", C_LGREY);
        fill_rect(x - 1, y + 3, iw + 2, 16, C_BLACK);
        fill_rect(x, y + 4, 21, 14, c);
        fill_rect(x + 2, y + 6, 17, 2, C_WHITE);
        fill_rect(x + 21, y + 4, 9, 14, C_YELLOW);
        fill_rect(x + 23, y + 4, 1, 14, C_BLACK);
        txt2(x + iw + 9, y + 1, w, C_BLACK);
        txt2(x + iw + 8, y, w, c);
    }
    if (V.blackout) fill_rect(0, 0, 320, 240, V.red ? C_RED : C_BLACK);
    if (V.banner) {
        if (text_w2(V.banner) <= 312) txt2_shc(160, 106, V.banner, V.ban_col);
        else txt_shc(160, 112, V.banner, V.ban_col);
    }
    if (V.text) txt_wrap(V.text, V.text_len, 200, C_WHITE);
    else if (V.name) {
        txt_shc(160, V.desc ? 190 : 206, V.name, C_WHITE);
        if (V.desc) {
            char lines[3][64];
            int nl = wrap(V.desc, lines);
            for (int l = 0; l < nl; l++) txt_shc(160, 204 + l * 12, lines[l], C_LGREY);
        }
    }
    g_ox = sx; g_oy = sy;
    V.dirty = false;
}

static bool synced;

static void copy_front(int y0, int y1) {
    const uint8_t *f = hw_front() + y0;
    uint8_t *b = hw_back + y0;
    for (int x = 0; x < 320; x++, f += 240, b += 240) memcpy(b, f, (size_t)(y1 - y0));
}
static void clip_rows(int *y0, int *y1);
static void frame(void) {
    compose();
    int b = buf_index();
    bufst[b].valid = !g_ox && !g_oy && !V.view;
    bufst[b].cam = V.cam;
    const kf_t *kf = clip_cur();
    bufst[b].flags = kf ? kf->flags : 0;
    clip_rows(&bufst[b].y0, &bufst[b].y1);
    clip_cols(&bufst[b].x0, &bufst[b].x1);
    hw_swap();
    synced = false;
}

static void clip_frame(void) {
    int b = buf_index();
    const kf_t *kf = clip_cur();
    uint8_t fl = kf ? kf->flags : 0;
    if (!bufst[b].valid || bufst[b].cam != V.cam || bufst[b].flags != fl || g_ox || g_oy || V.view || (CL2.id >= 0 && !CL2.held) || CL2.tail || V.eject_lbl ||
        (kf && kf->cam == CAM_FULL)) {
        if (CL2.tail) CL2.tail--;
        frame();
        return;
    }

    int y0, y1, x0, x1;
    clip_rows(&y0, &y1);
    clip_cols(&x0, &x1);
    int a0 = y0 < bufst[b].y0 ? y0 : bufst[b].y0, a1 = y1 > bufst[b].y1 ? y1 : bufst[b].y1;
    int e0 = x0 < bufst[b].x0 ? x0 : bufst[b].x0, e1 = x1 > bufst[b].x1 ? x1 : bufst[b].x1;
    if (a1 > a0 && e1 > e0) {
        g_clip0 = a0 < 0 ? 0 : a0; g_clip1 = a1 > 240 ? 240 : a1;
        g_cx0 = e0 < 0 ? 0 : e0; g_cx1 = e1 > 320 ? 320 : e1;
        compose();
        g_clip0 = 0; g_clip1 = 240; g_cx0 = 0; g_cx1 = 320;
    }

    bufst[b].y0 = y0; bufst[b].y1 = y1; bufst[b].x0 = x0; bufst[b].x1 = x1;
    hw_swap();
    synced = false;
}

static void sync_bufs(void) {
    if (synced) return;
    memcpy(hw_back, hw_front(), 320 * 240);
    synced = true;
}

static uint8_t ol_under[2][2400];
static int ol_cur = -1, ol_buf;
static const uint8_t *my_items(void) { return side ? G.it_d : G.it_p; }
static int sel_mask(int sel) {
    if (sel < 0) return NOMASK;
    if (sel == 8) return gun_ol();
    uint8_t k = my_items()[sel];
    return k ? item_ol[OLSET][k][sel] : NOMASK;
}

static void ol_runs(uint8_t *buf, int m, uint8_t *under, int mode) {
    if (m == NOMASK) return;
    const uint8_t *p = msk(m);
    int col = p[0], row = p[1] | p[2] << 8, h = p[4] | p[5] << 8;
    p += 6;
    int k = 0;
    for (int r = 0; r < h; r++, row++) {
        uint8_t *d = buf + row * 240 + col;
        for (;;) {
            uint8_t sk = *p++;
            if (sk == 0xFF) break;
            uint8_t n = *p++;
            d += sk;
            if (n && k + n <= (int)sizeof ol_under[0]) {
                if (mode == 2) memcpy(d, under + k, n);
                else {
                    if (mode == 0) memcpy(under + k, d, n);
                    memset(d, C_WHITE, n);
                }
                k += n;
            }
            d += n;
        }
    }
}

static void fx_update(void);
static void poll(void) {
    hw_poll();
    fx_update();
    clip2_update();
    if (hw_pressed & K_CLEAR) {
        hw_exit();
        exit(0);
    }
    if (hw_pressed & K_MODE) V.skip_talk = true;
}

static void recolor_mask(uint8_t *buf, int m, uint8_t from, uint8_t to) {
    const uint8_t *p = msk(m);
    int col = p[0], row = p[1] | p[2] << 8, h = p[4] | p[5] << 8;
    p += 6;
    for (int r = 0; r < h; r++) {
        uint8_t *d = buf + (row + r) * 240 + col;
        for (;;) {
            uint8_t sk = *p++;
            if (sk == 0xFF) break;
            uint8_t n = *p++;
            d += sk;
            for (uint8_t i = 0; i < n; i++) if (d[i] == from) d[i] = to;
            d += n;
        }
    }
}
static void recolor_rect(uint8_t *buf, int y0, int y1, uint8_t from, uint8_t to) {
    for (int x = 0; x < 320; x++) {
        uint8_t *d = buf + x * 240;
        for (int y = y0; y < y1; y++) if (d[y] == from) d[y] = to;
    }
}
static void recolor_choice(uint8_t *buf, int target) {
    uint8_t on = C_WHITE, off = G.two_p ? C_DGREY : C_MGREY;
    if (G.two_p) {
        recolor_rect(buf, 160, 192, target == 0 ? off : on, target == 0 ? on : off);
        recolor_rect(buf, 192, 224, target == 1 ? off : on, target == 1 ? on : off);
    } else {
        recolor_mask(buf, M_TXT_DEALER, target == 0 ? off : on, target == 0 ? on : off);
        recolor_mask(buf, M_TXT_YOU, target == 1 ? off : on, target == 1 ? on : off);
    }
}

static void txt_rows(void) {
    int b = buf_index();
    if (!bufst[b].valid || bufst[b].cam != V.cam || V.view || CL.id >= 0 || !V.text) { frame(); return; }
    char lines[3][64];
    int nl = wrap(V.text, lines);
    int y0 = 200 - nl * (FONT_H + 2) / 2;
    g_clip0 = y0 - 1; g_clip1 = y0 + nl * (FONT_H + 2) + 2;
    if (g_clip1 > 240) g_clip1 = 240;
    compose();
    g_clip0 = 0; g_clip1 = 240;

    hw_swap();
    synced = false;
}

static void step(void) {
    poll();
    bool typed_more = false;
    if (V.text && V.text[V.text_len]) {
        unsigned typed = (unsigned)((hw_now - V.text_t0) / MS(28));
        unsigned n = (unsigned)strlen(V.text);
        if (typed > n) typed = n;
        if (typed != V.text_len) { V.text_len = (uint16_t)typed; typed_more = true; }
    }
    if (V.view == VW_HEALTH && (V.hp_p == 1 || V.hp_d == 1)) {
        static uint8_t ph;
        uint8_t n = (uint8_t)((hw_now >> 12) & 1);
        if (n != ph) { ph = n; V.dirty = true; }
    }
    if (V.dirty) frame();
    else if (typed_more) txt_rows();
}

void pr_wait(unsigned ms) {
    tick_t end = hw_ticks() + MS(ms);
    do step(); while ((int)(end - hw_now) > 0);
}

static void cut_to(int view);
static uint8_t next_slow;
static void clip_play(int id, bool hold) {
    if (V.view != VW_TABLE) cut_to(VW_TABLE);
    CL.id = id; CL.t0 = hw_ticks(); CL.i = 0; CL.hold = hold; CL.done = false; CL.dx = CL.dy = 0; CL.slow = next_slow ? next_slow : 1; next_slow = 0;
    hw_now = CL.t0;
    bufst[0].valid = bufst[1].valid = false;
    for (;;) {
        clip_update();
        clip_frame();
        if (CL.done) {
            if (!CL.hold) CL.id = -1;
            break;
        }
        poll();
    }
    mark();
}
static void clip_stop(void) { CL.id = -1; mark(); }
static void clip_upto(int id, unsigned ms) {
    CL.id = id; CL.t0 = hw_ticks(); CL.i = 0; CL.hold = true; CL.done = false; CL.dx = CL.dy = 0; CL.slow = 1;
    hw_now = CL.t0;
    bufst[0].valid = bufst[1].valid = false;
    do { clip_update(); clip_frame(); poll(); } while (!CL.done && (int)(hw_now - CL.t0) < (int)MS(ms));
    mark();
}

void say_hold(const char *s) {
    camera(VIEW_ENEMY);
    V.text = s; V.text_len = 0; V.text_t0 = hw_ticks(); mark();
}
void pr_hide(void) { V.text = NULL; mark(); }
static void talk_wait(unsigned ms);
static void say_here(const char *s, unsigned ms) {
    if (V.skip_talk) { pr_wait(600); return; }
    V.text = s; V.text_len = 0; V.text_t0 = hw_ticks(); mark();
    talk_wait(ms);
    V.text = NULL; mark();
}
static void talk_wait(unsigned ms) {
    tick_t end = hw_ticks() + MS(ms);
    do {
        step();
        if (V.skip_talk) return;
        if (hw_pressed & K_OK) {
            if (V.text && V.text[V.text_len]) { V.text_len = (uint16_t)strlen(V.text); V.text_t0 = hw_now - MS(28) * V.text_len; mark(); }
            else return;
        }
    } while ((int)(end - hw_now) > 0);
}
void pr_say(const char *s, unsigned ms) {
    if (V.skip_talk) return;
    say_hold(s);
    talk_wait(ms);
    pr_hide();
}

enum { FX_NONE, FX_MUZZLE, FX_REVIVE };
static tick_t fx_t0;
static void fx_update(void);
static void fx_start(uint8_t mode) { fx_mode = mode; fx_t0 = hw_ticks(); fx_update(); }
static unsigned ms_since(tick_t t0) { return (unsigned)(((unsigned long)((hw_ticks() - t0) & 0xFFFFFF) * 125u) >> 12); }

static tick_t kick_t0;
static uint16_t kick_len;
static uint8_t kick_amp;
static void kick(uint8_t amp, unsigned ms) { kick_amp = amp; kick_len = (uint16_t)ms; kick_t0 = hw_ticks(); }
static void kick_stop(void) { kick_len = 0; g_ox = g_oy = 0; }

static tick_t lens_t0;
static bool lens_on;
static void lens_blood(void) { V.splat = (int8_t)rnd(4); V.sp_fade = 0; lens_t0 = hw_ticks(); lens_on = true; }

static void fx_timers(void) {
    if (V.eject_lbl && ms_since(V.eject_t0) > 1800) { V.eject_lbl = 0; CL2.tail = 2; mark(); }
    if (kick_len) {
        unsigned t = ms_since(kick_t0);
        if (t >= kick_len) kick_stop();
        else {
            int r = (int)(kick_len - t), a = kick_amp * r / kick_len * r / kick_len + 1;
            int nx = (int)rnd((unsigned)(2 * a + 1)) - a, ny = (int)rnd((unsigned)(2 * a + 1)) - a;
            if ((nx > 0) == (g_ox > 0)) nx = -nx;
            g_ox = nx; g_oy = ny;
        }
        mark();
    }
    if (lens_on) {
        unsigned t = ms_since(lens_t0);
        int8_t f = t < 900 ? 0 : t < 1400 ? 1 : t < 1900 ? 2 : t < 2400 ? 3 : 4;
        if (f == 4) { V.splat = -1; lens_on = false; mark(); }
        else if (f != V.sp_fade) { V.sp_fade = f; mark(); }
    }
}

static void fx_update(void) {
    fx_timers();
    hw_pal_flush();
    if (!fx_mode) return;
    unsigned t = (unsigned)(((unsigned long)((hw_ticks() - fx_t0) & 0xFFFFFF) * 125u) >> 12);
    unsigned len = fx_mode == FX_MUZZLE ? 300 : 4000;
    if (t >= len) { fx_mode = FX_NONE; hw_pal_next(pal_base); mark(); return; }
    if (fx_mode == FX_REVIVE) {
        static unsigned last = 65535;
        t = t / 200 * 200;
        if (t == last && t) return;
        last = t;
    }
    static uint16_t p[256];
    int e = 0, k256 = 256, add_r = 0, add_g = 0;
    if (fx_mode == FX_MUZZLE) {
        e = t < 100 ? 100 - (int)t : 0;
        add_r = 18 * e / 100; add_g = 9 * e / 100;
        unsigned x = t * 256u / 300u, sm = (unsigned)((unsigned long)x * x * (768 - 2 * x) >> 16);
        k256 = 420 - (int)(164 * sm / 256);
    } else {
        k256 = 256 + (int)(678L * (4000 - t) / 4000);
    }
    for (int i = 0; i < 256; i++) {
        if (i == PAL_USED) i = 240;
        uint16_t c = pal_base[i];
        if (i >= 240) { p[i] = c; continue; }
        int r = ((c >> 10) & 31) << 1, g = ((c >> 5) & 31) << 1 | (c >> 15), b = (c & 31) << 1;
        if (fx_mode == FX_MUZZLE) {
            r = ((r + add_r - 32) * k256 >> 8) + 32; g = ((g + add_g - 32) * k256 >> 8) + 32; b = ((b - 32) * k256 >> 8) + 32;
        } else {
            r = r * k256 >> 8; g = g * k256 >> 8; b = b * k256 >> 8;
        }
        r = r < 0 ? 0 : r > 63 ? 63 : r; g = g < 0 ? 0 : g > 63 ? 63 : g; b = b < 0 ? 0 : b > 63 ? 63 : b;
        p[i] = (uint16_t)((r >> 1) << 10 | (g >> 1) << 5 | (b >> 1) | (g & 1) << 15);
    }
    hw_pal_next(p);
    mark();
}

static void fade_pal(bool out, unsigned ms);
static void fade(bool out, unsigned ms) {
    if (!out && V.dirty) {
        static uint16_t black[256];
        hw_pal(black, 0, 256);
        pal_hold = true;
        frame();
        pal_hold = false;
    }
    fade_pal(out, ms);
}

void pr_fade(bool out, unsigned ms) { memcpy(pal_base, pal16, sizeof pal_base); pal_key = -1; fade_pal(out, ms); }
static void fade_pal(bool out, unsigned ms) {
    static uint16_t p[256];
    tick_t t0 = hw_ticks(), span = MS(ms);
    int last = -1;
    for (;;) {
        poll();
        unsigned t = (unsigned)(hw_now - t0);

        int lv = t >= span ? 12 : (int)(t * 12u / span);
        if (lv == last) continue;
        last = lv;
        unsigned k = (unsigned)(lv * 32 / 12);
        if (out) k = 32 - k;
        for (int i = 0; i < 256; i++) {
            if (i == PAL_USED) i = 240;
            uint16_t c = pal_base[i];
            unsigned r = (c >> 10) & 31, g = (c >> 5) & 31, b = c & 31;
            p[i] = (uint16_t)((r * k / 32) << 10 | (g * k / 32) << 5 | (b * k / 32) | (c & 0x8000));
        }
        hw_pal(p, 0, 256);
        if (t >= span) break;
    }
}

static void cut_to(int view) {
    if (V.view == view) return;
    fade(true, 110);
    V.view = view;
    V.dirty = true;
    frame();
    fade(false, 130);
}

static void camera(int view) {
    if (V.view != VW_TABLE) cut_to(VW_TABLE);
    int to = view == VIEW_ENEMY ? PAN_N : 0, from = V.cam;
    if (from == to) return;
    tick_t t0 = hw_ticks(), span = MS(700);
    for (;;) {
        poll();
        unsigned t = (unsigned)(hw_now - t0) + MS(17);
        if (t >= span) break;
        unsigned x = t * 256u / span;
        unsigned e = (unsigned)((unsigned long)x * x * (768 - 2 * x) >> 16);
        V.cam = from + (to - from) * (int)e / 256;
        frame();
    }
    V.cam = to;
    frame();
}

void pr_arrive(void) {
    V.d_away = false; V.gun_down = true; V.sel = -1; V.cam = PAN_N; V.view = VW_TABLE;
    mark();
    fade(false, 700);
    pr_wait(400);
}

